function update(dt) {
    // Player movement handling
    const left = keys.has('ArrowLeft') || keys.has('a') || keys.has('A');
    const right = keys.has('ArrowRight') || keys.has('d') || keys.has('D');
    const up = keys.has('ArrowUp') || keys.has('w') || keys.has('W');
    const down = keys.has('ArrowDown') || keys.has('s') || keys.has('S');
    // Horizontal acceleration
    if (left) player.vx -= PLAYER_ACCEL * dt;
    if (right) player.vx += PLAYER_ACCEL * dt;
    // Vertical acceleration
    if (up) player.vy -= PLAYER_ACCEL * dt;
    if (down) player.vy += PLAYER_ACCEL * dt;
    // Clamp speed
    const speed = Math.hypot(player.vx, player.vy);
    if (speed > PLAYER_MAX_SPEED) {
      const scale = PLAYER_MAX_SPEED / speed;
      player.vx *= scale;
      player.vy *= scale;
    }
    // Apply friction
    const decay = Math.pow(PLAYER_FRICTION, dt);
    player.vx *= decay;
    player.vy *= decay;
    // Update position and wrap
    player.x = (player.x + player.vx * dt + W) % W;
    player.y = (player.y + player.vy * dt + H) % H;
    // TODO: other game logic
  }

